export type RuntimeArtifactPathMatcher =
  | { kind: 'exact'; value: string }
  | { kind: 'prefix'; value: string }
  | { kind: 'regexp'; value: RegExp };

export interface RuntimeArtifactRegistryEntry {
  id: string;
  description: string;
