   432	function proposalOverlap(a: HostKeywordProposal, b: HostKeywordProposal): number {
   433	  const left = proposalTermSet(a);
   434	  const right = proposalTermSet(b);
   435	  if (left.size === 0 && right.size === 0) return 1;
   436	  const intersection = [...left].filter(term => right.has(term)).length;
   437	  return intersection / Math.max(left.size, right.size, 1);
   438	}
